const content = $json.choices[0].message.content;

const cleaned = content
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

const result = JSON.parse(cleaned);

return [{ json: result }];

