{{
(() => {
  const data = $('Prepare Application Report').first().json;
  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({
    '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'
  }[c]));

  const skills = (v) => {
    if (Array.isArray(v)) return v.map(esc).join(', ');
    return esc(v || 'Not specified');
  };

  const score = Number(data.fit_score || 0);
  const scoreColor = score >= 75 ? '#16803c' : score >= 50 ? '#b7791f' : '#c53030';

  return `
  <div style="margin:0;background:#f3f5f9;padding:28px 12px;font-family:Arial,Helvetica,sans-serif;color:#243047;">
    <div style="max-width:680px;margin:auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;">
      <div style="background:#172554;padding:26px 30px;color:#ffffff;">
        <div style="font-size:12px;letter-spacing:1.5px;color:#bfdbfe;">JOB APPLICATION AUTOPILOT</div>
        <h1 style="font-size:24px;margin:12px 0 6px;">Your Resume Analysis</h1>
        <p style="font-size:14px;margin:0;color:#dbeafe;">Personalized insights for your job application</p>
      </div>

      <div style="padding:28px 30px;">
        <p style="font-size:16px;">Hello ${esc(data.applicant_name || 'Candidate')},</p>
        <p style="font-size:14px;line-height:1.7;color:#475569;">We've analysed your resume against the job details you submitted. Here's a summary to help you understand your alignment with the role.</p>

        <table style="width:100%;border-collapse:collapse;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;">
          <tr><td style="padding:12px;border-bottom:1px solid #e2e8f0;color:#64748b;">Position</td><td style="padding:12px;border-bottom:1px solid #e2e8f0;font-weight:bold;">${esc(data.job_title)}</td></tr>
          <tr><td style="padding:12px;color:#64748b;">Company</td><td style="padding:12px;font-weight:bold;">${esc(data.company_name)}</td></tr>
        </table>

        <div style="margin:24px 0;padding:20px;text-align:center;background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;">
          <div style="font-size:13px;color:#64748b;">ESTIMATED RESUME–JOB MATCH</div>
          <div style="font-size:38px;font-weight:bold;color:${scoreColor};margin:8px 0;">${esc(score)}/100</div>
          <div style="font-size:12px;color:#64748b;">AI-generated estimate, not a hiring decision</div>
        </div>

        <h2 style="font-size:18px;color:#172554;">Analysis Summary</h2>
        <p style="font-size:14px;line-height:1.8;color:#475569;white-space:pre-line;">${esc(data.reasoning || 'No reasoning provided.')}</p>

        <h2 style="font-size:18px;color:#172554;">Matching Skills</h2>
        <p style="font-size:14px;line-height:1.8;color:#166534;">${skills(data.matching_skills)}</p>

        <h2 style="font-size:18px;color:#172554;">Skills to Improve</h2>
        <p style="font-size:14px;line-height:1.8;color:#9a3412;">${skills(data.missing_skills)}</p>

        <div style="height:1px;background:#e2e8f0;margin:28px 0;"></div>
        <h2 style="font-size:21px;color:#172554;">Your Personalized Cover Letter</h2>
        <div style="font-size:14px;line-height:1.9;color:#334155;white-space:pre-line;">${esc(data.cover_letter || 'No cover letter was generated.')}</div>

        <p style="font-size:13px;line-height:1.7;color:#64748b;margin-top:28px;">Tip: Review the cover letter and verify all qualifications, dates, links and contact details before using it to apply.</p>
      </div>

      <div style="background:#f8fafc;border-top:1px solid #e2e8f0;padding:18px 30px;color:#64748b;font-size:12px;line-height:1.6;">
        Generated by Job Application Autopilot<br>
        This report is intended to support your job search. The match score is an estimate, not a guarantee of selection.
      </div>
    </div>
  </div>`;
})()
}}
